"""==============================================================================IOTEC106_MISSION_ENGINE.py==============================================================================Gerenciador Central de Missões=============================================================================="""from __future__ import annotationsimport sqlite3import uuidfrom pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class MissionEngine:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row        self.create_table()    # ------------------------------------------------------------------    def create_table(self):        self.conn.execute("""        CREATE TABLE IF NOT EXISTS missions(            mission_uuid TEXT PRIMARY KEY,            title TEXT,            description TEXT,            priority TEXT,            status TEXT,            assigned_agent TEXT,            created_at TEXT,            started_at TEXT,            finished_at TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def create(        self,        title,        description,        assigned_agent,        priority="NORMAL"    ):        mission_uuid = str(uuid.uuid4())        now = datetime.utcnow().isoformat()        self.conn.execute("""        INSERT INTO missions(            mission_uuid,            title,            description,            priority,            status,            assigned_agent,            created_at,            started_at,            finished_at        )        VALUES(?,?,?,?,?,?,?,?,?)        """,(            mission_uuid,            title,            description,            priority,            "PENDING",            assigned_agent,            now,            None,            None        ))        self.conn.commit()        return mission_uuid    # ------------------------------------------------------------------    def start(self, mission_uuid):        self.conn.execute("""        UPDATE missions        SET            status='RUNNING',            started_at=?        WHERE mission_uuid=?        """,(            datetime.utcnow().isoformat(),            mission_uuid        ))        self.conn.commit()    # ------------------------------------------------------------------    def finish(self, mission_uuid):        self.conn.execute("""        UPDATE missions        SET            status='FINISHED',            finished_at=?        WHERE mission_uuid=?        """,(            datetime.utcnow().isoformat(),            mission_uuid        ))        self.conn.commit()    # ------------------------------------------------------------------    def list(self):        rows = self.conn.execute("""        SELECT *        FROM missions        ORDER BY created_at DESC        """).fetchall()        return [dict(r) for r in rows]# =============================================================================if __name__ == "__main__":    engine = MissionEngine()    mission = engine.create(        title="Criar EVENT BUS",        description="Desenvolver o módulo 103_EVENT_BUS_ENGINE",        assigned_agent="AG001",        priority="HIGH"    )    print("\nMISSÃO:", mission)    engine.start(mission)    engine.finish(mission)    print()    for item in engine.list():        print(item)